import { getTelemetryMode } from '../../config/telemetryPolicy';
import { PROFILE_PREPARATION_BODY_BYTES } from '../../types/design-profile';
import { json, Router, type ErrorRequestHandler } from 'express';
import { installationChannel } from '../../install/installationChannel';
import { RIVET_VERSION } from '../../config/telemetry';
import {
  authenticateLibrary,
  handleLibraryError,
  trackLibraryOperation,
  isLocalHost,
} from './middleware';
import { createProjectRoutes } from './projects';
import { createVariantRoutes } from './variants';
import { createNavigationRoutes } from './navigation';
import type { LibraryRouteOptions } from './types';
import { createProfileRoutes } from './profiles';
import { createBrowserAccessRouter } from './browserAccess';
import { getPluginName } from '../../hosts/pluginContext';

const REQUEST_BODY_LIMIT = '256kb';
const GUIDANCE_UPLOAD_BYTES = 50 * 1024 * 1024;

const handleGuidanceUploadError: ErrorRequestHandler = (
  error: unknown,
  _req,
  res,
  next,
) => {
  if (
    typeof error !== 'object' ||
    error === null ||
    !('type' in error) ||
    error.type !== 'entity.too.large'
  ) {
    next(error);
    return;
  }
  res.status(413).json({
    code: 'guidance_upload_too_large',
    error:
      'The context upload exceeds the 50 MiB HTTP request limit and was not saved. Split the source into smaller documents or reduce the uploaded source and retry. This is an upload limit, not a model context limit.',
  });
};

export const createLibraryRouter = (options: LibraryRouteOptions): Router => {
  const router = Router();
  const services = {
    ...options,
    track: trackLibraryOperation(options.telemetry),
  };
  if (options.browserSessions)
    router.use(
      createBrowserAccessRouter({
        token: options.token,
        sessions: options.browserSessions,
        telemetry: options.telemetry,
      }),
    );
  router.get('/health', authenticateLibrary(options.token), (_req, res) =>
    res.json({
      pid: process.pid,
      instanceId: options.token,
      channel: installationChannel(),
      rivetVersion: RIVET_VERSION,
      pluginName: getPluginName(),
      telemetryMode: getTelemetryMode(),
      isSourceSyncStarted: options.profiles?.sourceSync.isActive ?? false,
    }),
  );
  router.use(authenticateLibrary(options.token, options.browserSessions));
  router.put(
    '/source-sync/schedule',
    authenticateLibrary(options.token),
    (req, res) => {
      if (!isLocalHost(req)) return res.sendStatus(403);
      options.profiles?.sourceSync.start();
      return res.json({
        isSourceSyncStarted: options.profiles?.sourceSync.isActive ?? false,
      });
    },
  );
  router.post(
    '/profile/preparations',
    json({ limit: PROFILE_PREPARATION_BODY_BYTES }),
  );
  router.post('/guidance', json({ limit: GUIDANCE_UPLOAD_BYTES }));
  router.patch('/guidance/:id', json({ limit: GUIDANCE_UPLOAD_BYTES }));
  router.use('/guidance', handleGuidanceUploadError);
  router.use(json({ limit: REQUEST_BODY_LIMIT }));
  router.use(createProjectRoutes(services));
  router.use(createVariantRoutes(services));
  router.use(createNavigationRoutes(services));
  if (options.profiles)
    router.use(createProfileRoutes(options.profiles, options.telemetry));
  router.use(handleLibraryError);
  return router;
};
